  s1.id AS dotted_id,
  s2.id AS underscored_id,
  s3.id AS dashed_id,
  s4.id AS numeric_id,
  s5.id AS unicode_id,
  s6.id AS accented_id,
  s7.id AS combining_id,
  s8.id AS uppercase_id,
  s9.id AS lowercase_id,
  s10.id AS keyword_id,
  s11.id AS punctuation_id,
  s12.id AS hidden_id,
  s13.id AS prefix_id,
  s14.id AS literal_id,
  s15.id AS overridden_id,
  s16.id AS slash_id,
  s17.id AS space_id,
  s18.id AS trailing_dot_id,
  s19.id AS device_id,
  s20.id AS prototype_id,
  s21.id AS numeric_literal_id
